record Order(Long id, String customerId, double amount, boolean isPaid) {}

class OrderService {
    public List<String> getUnpaidHighValueCustomers(List<Order> orders) {
        return orders.stream()
            .filter(order -> !order.isPaid())           // Keep only unpaid orders
            .filter(order -> order.amount() > 1000.0)   // Keep only high-value orders
            .map(Order::customerId)                      // Transform Order to customerId
            .distinct()                                   // Remove duplicate customers
            .collect(Collectors.toList());               // Terminal operation
    }

    public List<String> formatActiveOrderSummaries(List<Order> orders) {
        return orders.stream()
            .filter(Order::isPaid)                       // Selection: only paid orders
            .map(order -> String.format(                 // Transformation: Order to String
                "Order #%d: $%.2f", 
                order.id(), 
                order.amount()
            ))
            .collect(Collectors.toList());
    }
}

record Order(Long id, String customerId, double amount, String status) {}

class OrderRepository {
    public List<Order> getHighValueOrders(List<Order> orders) {
        return orders.stream()
            .filter(order -> order.amount() > 1000.0)
            .collect(Collectors.toList());               // Basic collection
    }

    public Map<String, List<Order>> groupOrdersByCustomer(List<Order> orders) {
        return orders.stream()
            .collect(Collectors.groupingBy(Order::customerId));  // Group by key
    }

    public Map<Long, Order> createOrderLookupMap(List<Order> orders) {
        return orders.stream()
            .collect(Collectors.toMap(
                Order::id,                               // Key mapper
                order -> order                           // Value mapper (identity)
            ));
    }

    public Map<String, Double> getTotalRevenueByCustomer(List<Order> orders) {
        return orders.stream()
            .collect(Collectors.groupingBy(
                Order::customerId,
                Collectors.summingDouble(Order::amount)  // Downstream collector
            ));
    }
}

record Product(String id, String name, double price, String category) {}

class ProductService {
    public List<Product> getTopExpensiveUniqueProducts(List<Product> products, int count) {
        return products.stream()
            .filter(p -> p.price() > 0)                          // Remove invalid prices
            .distinct()                                           // Remove duplicates
            .sorted(Comparator.comparingDouble(Product::price)    // Sort by price
                .reversed())                                      // High to low
            .limit(count)                                         // Take top N
            .collect(Collectors.toList());
    }

    public List<String> getTopCategoriesByName(List<Product> products) {
        return products.stream()
            .map(Product::category)
            .distinct()                                           // Unique categories
            .sorted()                                             // Natural order (alphabetical)
            .limit(5)
            .collect(Collectors.toList());
    }

    public List<Product> getAffordableProductsSorted(List<Product> products, double maxPrice) {
        return products.stream()
            .filter(p -> p.price() <= maxPrice)
            .sorted(Comparator.comparing(Product::name))          // Custom Comparator
            .collect(Collectors.toList());
    }
}

record Order(Long id, String status, double amount, boolean isPaid) {}

class OrderValidator {
    public boolean hasAnyUnpaidOrders(List<Order> orders) {
        return orders.stream()
            .anyMatch(order -> !order.isPaid());             // Stops on first unpaid
    }

    public boolean areAllOrdersCompleted(List<Order> orders) {
        return orders.stream()
            .allMatch(order -> "COMPLETED".equals(order.status()));  // Stops on first non-completed
    }

    public boolean hasNoHighValueOrders(List<Order> orders, double threshold) {
        return orders.stream()
            .noneMatch(order -> order.amount() > threshold); // Stops on first high-value
    }

    public boolean canProcessBatch(List<Order> orders) {
        boolean hasOrders = !orders.isEmpty();
        boolean allPaid = orders.stream().allMatch(Order::isPaid);
        boolean noNegativeAmounts = orders.stream()
            .noneMatch(order -> order.amount() < 0);

        return hasOrders && allPaid && noNegativeAmounts;    // Combine multiple checks
    }
}

record OrderItem(String productName, int quantity) {}
record Order(Long id, String customerId, List<OrderItem> items) {}

class OrderAnalytics {
    public void demonstrateMapVsFlatMap(List<Order> orders) {
        // Using map() - creates nested structure
        Stream<List<OrderItem>> nestedStream = orders.stream()
            .map(Order::items);                          // Stream<List<OrderItem>>
        // Awkward to work with - you'd need forEach with nested loop

        // Using flatMap() - flattens to single stream
        List<OrderItem> allItems = orders.stream()
            .flatMap(order -> order.items().stream())    // Stream<OrderItem>
            .collect(Collectors.toList());
    }

    public Map<String, Long> getProductPopularity(List<Order> orders) {
        return orders.stream()
            .flatMap(order -> order.items().stream())    // Flatten all items
            .collect(Collectors.groupingBy(
                OrderItem::productName,
                Collectors.summingLong(OrderItem::quantity)
            ));
    }
}

record Order(Long id, double amount, int itemCount) {}

class OrderAnalytics {
    public double calculateTotalRevenue(List<Order> orders) {
        return orders.stream()
            .map(Order::amount)
            .reduce(0.0, (sum, amount) -> sum + amount);     // With identity
        // Alternative: .reduce(0.0, Double::sum);
    }

    public Optional<Order> findLargestOrder(List<Order> orders) {
        return orders.stream()
            .reduce((order1, order2) ->                      // Without identity
                order1.amount() > order2.amount() ? order1 : order2
            );  // Returns Optional<Order> for empty stream safety
    }

    public int getTotalItemCount(List<Order> orders) {
        return orders.stream()
            .map(Order::itemCount)
            .reduce(0, Integer::sum);                        // Identity = 0
    }

    public String buildOrderSummary(List<Order> orders) {
        return orders.stream()
            .map(order -> String.format("#%d: $%.2f", order.id(), order.amount()))
            .reduce("", (acc, str) -> acc.isEmpty() ? str : acc + ", " + str);
    }
}

