import java.util.List;
import java.util.Optional;

public class FindFirstVsFindAny {
    public static void main(String[] args) {
        var names = List.of("amy", "bob", "ben", "cat");

        // findFirst: deterministic, respects encounter order
        Optional<String> first = names.stream()
            .filter(n -> n.startsWith("b"))
            .findFirst();           // always "bob"

        // findAny: any match; may differ under parallel()
        Optional<String> any = names.parallelStream()
            .filter(n -> n.startsWith("b"))
            .findAny();             // "bob" or "ben"

        System.out.println(first.get() + " / " + any.get());
    }
}
